import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

public class Partial_withField_TriageGen2Test {

    @Test
    public void testWithField_ReturnsSameInstanceWhenValueIsUnchanged() {
        // Arrange
        DateTimeFieldType yearType = DateTimeTypes.year();
        int value = 2023;
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{value});

        // Act
        Partial result = partial.withField(yearType, value);

        // Assert
        // The code says: if (value == getValue(index)) { return this; }
        assertSame("Should return the same instance if value is unchanged", partial, result);
    }

    @Test
    public void testWithField_ReturnsNewInstanceWhenValueIsChanged() {
        // Arrange
        DateTimeFieldType yearType = DateTimeTypes.year();
        DateTimeFieldType monthType = DateTimeTypes.monthOfYear();
        int[] types = {yearType.getSortOrder().compareTo(monthType.getSortOrder()) == 0 ? 0 : 0, 0}; // Dummy index logic
        // Using constructor with types and values for clarity
        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2023, 1});

        // Act
        Partial result = partial.withField(yearType, 2024);

        // Assert
        assertNotSame("Should return a new instance when value changes", partial, result);
        assertEquals("Year should be updated to 2024", 2024, result.getValue(0));
        assertEquals("Month should remain 1", 1, result.getValue(1));
    }

    @Test
    public void testWithField_UpdatesCorrectIndex() {
        // Arrange
        DateTimeFieldType yearType = DateTimeTypes.year();
        DateTimeFieldType monthType = DateTimeTypes.monthOfYear();
        DateTimeFieldType dayType = DateTimeTypes.dayOfMonth();

        Partial partial = new Partial(
                new DateTimeFieldType[]{yearType, monthType, dayType},
                new int[]{2023, 5, 15}
        );

        // Act
        // Change the middle field (month)
        Partial result = partial.withField(monthType, 12);

        // Assert
        assertEquals("Year should remain 2023", 2023, result.getValue(0));
        assertEquals("Month should be updated to 12", 12, result.getValue(1));
        assertEquals("Day should remain 15", 15, result.getValue(2));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testWithField_ThrowsExceptionWhenFieldNotSupported() {
        // Arrange
        // Create a partial that only contains Year
        Partial partial = new Partial(new DateTimeFieldType[]{DateTimeTypes.year()}, new int[]{2023});

        // Act
        // Attempt to update Month which is not in the partial's field types
        // This should trigger indexOfSupported to fail or return invalid index
        partial.withField(DateTimeTypes.monthOfYear(), 1);
    }
}
